//! Passive optgroup connection preserves actual identity and ownership.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><div id=target>Fallback group<span id=tail>Tail</span></div><select id=select><optgroup id=group label=Group><option value=one>One</option></optgroup></select><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://optgroup-adoption.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}


#[test]
fn optgroup_adoption_native_detached_roundtrip_keeps_exact_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.createElement('optgroup'),owner=new Document();x.label='A\ud800Z';x.disabled=true;var attr=x.getAttributeNode('label'),state={marker:17},view=x.childNodes;x.authorState=state;if(owner.adoptNode(x)!==x||x.parentNode!==null||x.ownerDocument!==owner||attr.ownerDocument!==owner||x.getAttributeNode('label')!==attr||x.label!=='A\ud800Z'||!x.disabled||x.authorState!==state||x.childNodes!==view)throw 'actual detached group adoption';if(document.adoptNode(x)!==x||x.ownerDocument!==document||attr.ownerDocument!==document||x.getAttributeNode('label')!==attr||x.label!=='A\ud800Z'||!x.disabled)throw 'actual group owner return';var target=document.getElementById('target');target.appendChild(x);if(x.parentNode!==target||x.ownerDocument!==document||x.getAttributeNode('label')!==attr)throw 'adopted group reconnect';"#);}
#[test]
fn optgroup_adoption_connected_passive_tree_removes_and_rebinds_actual_descendants(){let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();let native=format!("{:?}",f.controls[&select].select);run(&mut d,&mut f,&mut p,r#"var target=document.getElementById('target');target.innerHTML='<optgroup label=Parsed disabled>Text<!--marker--><span>Child</span></optgroup>';var x=target.firstChild,attr=x.getAttributeNode('label'),list=x.childNodes,text=x.firstChild,comment=text.nextSibling,child=x.lastChild,owner=new Document(),watch=new MutationObserver(function(){});watch.observe(target,{childList:true});if(owner.adoptNode(x)!==x||target.firstChild!==null||x.parentNode!==null||x.ownerDocument!==owner||attr.ownerDocument!==owner||text.ownerDocument!==owner||comment.ownerDocument!==owner||child.ownerDocument!==owner||x.childNodes!==list||list.length!==3||list[0]!==text||list[1]!==comment||list[2]!==child||text.data!=='Text'||comment.data!=='marker'||x.label!=='Parsed'||!x.disabled)throw 'actual connected passive group adoption';var records=watch.takeRecords();if(records.length!==1||records[0].removedNodes[0]!==x||records[0].target!==target)throw 'actual group removal record';document.adoptNode(x);target.appendChild(x);if(x.parentNode!==target||x.ownerDocument!==document||child.ownerDocument!==document||x.getAttributeNode('label')!==attr||attr.ownerDocument!==document||x.childNodes!==list)throw 'actual passive group return';"#);assert_eq!(format!("{:?}",f.controls[&select].select),native);}

#[test]
fn optgroup_adoption_resource_refusals_preserve_real_source_then_recover(){
 for mode in 0..4{
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var source=document.createElement('optgroup'),target=document.getElementById('target'),owner=new Document();source.label='Retained';source.disabled=true;target.appendChild(source);var attr=source.getAttributeNode('label'),watch=new MutationObserver(function(){});watch.observe(target,{childList:true});");
  p.state.rebuild(&d).unwrap();let tree=format!("{:?}",d.nodes);let before=(p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes(),p.state.attributes.len(),p.state.detached_nodes.clone());let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};
  let error=p.runtime.execute("owner.adoptNode(source);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("limit")||error.contains("bound")||error.contains("time"),"{mode}: {error}");
  assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!((p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes(),p.state.attributes.len(),p.state.detached_nodes.clone()),before);p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();
  run(&mut d,&mut f,&mut p,"if(source.parentNode!==target||source.ownerDocument!==document||attr.ownerDocument!==document||source.getAttributeNode('label')!==attr||source.label!=='Retained'||!source.disabled||watch.takeRecords().length)throw 'atomic group adoption refusal';if(owner.adoptNode(source)!==source||source.parentNode!==null||source.ownerDocument!==owner||attr.ownerDocument!==owner||source.getAttributeNode('label')!==attr||source.label!=='Retained'||!source.disabled||watch.takeRecords().length!==1)throw 'fresh group adoption recovery';");
  assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty()&&p.take_dynamic_stylesheets().is_empty());assert!(!p.state.images.has_changes());
 }
}
#[test]
fn optgroup_adoption_saved_child_method_revalidates_origin_before_removal(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var owner=new Document(),source=document.createElement('optgroup'),target=document.getElementById('target'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);source.label='Saved';target.appendChild(source);var saved=frame.contentWindow.Document.prototype.adoptNode,attr=source.getAttributeNode('label');");
 p.set_location(&crate::navigation::address("https://other-optgroup-adoption.test/",&crate::navigation::Location::home()).unwrap());p.state.rebuild(&d).unwrap();let tree=format!("{:?}",d.nodes);let before=(p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes());p.begin_job();let error=p.runtime.execute("saved.call(owner,source);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!((p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes()),before);
 p.set_location(&crate::navigation::address("https://optgroup-adoption.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(source.parentNode!==target||source.ownerDocument!==document||attr.ownerDocument!==document||source.label!=='Saved')throw 'denied adoption retains source';if(saved.call(owner,source)!==source||source.parentNode!==null||source.ownerDocument!==owner||attr.ownerDocument!==owner||source.getAttributeNode('label')!==attr)throw 'saved adoption fresh recovery';");
}
#[test]
fn optgroup_adoption_keeps_select_option_and_resource_descendant_guards(){
 let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();let native=format!("{:?}",f.controls[&select].select);run(&mut d,&mut f,&mut p,"var owner=new Document(),target=document.getElementById('target'),inside=document.getElementById('group'),option=inside.firstChild;target.innerHTML='<optgroup id=passive label=Guard><input id=nested value=seed></optgroup>';var passive=target.firstChild;");
 for source in ["inside","option","passive"]{let tree=format!("{:?}",d.nodes);let before=(p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes());p.begin_job();run(&mut d,&mut f,&mut p,&format!("var caught=false;try{{owner.adoptNode({source});}}catch(e){{caught=e.name==='NotSupportedError'&&e instanceof DOMException;}}if(!caught)throw 'actual lifecycle guard {source}';"));assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!((p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes()),before);assert_eq!(format!("{:?}",f.controls[&select].select),native);}
 p.begin_job();run(&mut d,&mut f,&mut p,"if(inside.parentNode!==document.getElementById('select')||option.parentNode!==inside||passive.parentNode!==target||document.getElementById('nested').value!=='seed')throw 'guard retains actual control tree';var fresh=document.createElement('optgroup');fresh.label='Fresh';if(owner.adoptNode(fresh)!==fresh||fresh.ownerDocument!==owner||fresh.label!=='Fresh')throw 'ordinary adoption after lifecycle refusal';");
}
